    'story.cat.righteous': 'Tabi\'ai da Salihai',
    'story.cat.children': 'Labarai na Yara',
    'story.cat.companions': 'Al\'amuran Sahabbai',
    'story.cat.battles': 'Yaƙe-Yaƙe',
  },
